def simulate_bubble_square(n, k, friendships):
    # Create a graph to represent the friendship network
    graph = defaultdict(lambda: {'in': 0, 'out': 0})
    for a, b in friendships:
        graph[a]['in'].add(b)
        graph[b]['out'].add(a)

    # Calculate the number of tokens each member should receive
    friend_colors = [0] * n
    for i in range(n):
        if len(graph[i]['out']) > len(graph[i]['in']):
            friend_colors[i] += 1

    tokens_needed = defaultdict(lambda: 0)

    for j in range(n):
        for item in graph[j]['out']:
            tokens_needed[item] += friend_colors[j]

    # Adjust tokens if a member is given more tokens than needed
    for member, tokens in tokens_needed.items():
        if tokens < friend_colors[member]:
            tokens_needed[member] = friend_colors[member]

    # Distribute tokens according to the tokens_needed dictionary
    for i in range(n):
        tokens = tokens_needed[i]
        for next_friend in graph[i]['out']:
