def shortest_path_factorial(n, m, graph, start, end, initial_weights):
    inf = float('inf')
    dist = [[inf] * (n + 1) for _ in range(n + 1)]
    paths = [[0] * (n + 1) for _ in range(n + 1)]

    # Init distances with numpy sparse matrix
    for i in range(1, n + 1):
        dist[i][i], paths[i][i] = 0, 1
        for j in range(1, n + 1):
            if i != j:
                dist[i][j], paths[i][j] = float('inf'), 0
                for k in range(n + 1):
                    if graph[i][j] and dist[i][k] and paths[k][j]:
                        if dist[i][j] > dist[i][k] + graph[i][j]:
                            dist[i][j], paths[i][j] = dist[i][k] + graph[i][j], paths[k][j]
                        elif dist[i][j] == dist[i][k] + graph[i][j] and paths[k][j] > paths[i][j]:
                            paths[i][j], paths[k][j] = paths[k][j], paths[i][j]

    # Calculate factorials for faster factorials in O(n)
    fact = [0] * (n + 1)
    fact[0] = 1
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i

    result = [0] * m
    step = 0
    scores = [initial_weights]

    def dfs(u, x):
        nonlocal step, result, scores
        if step > x * n:
            return
        if x < 0:
            return
        if dist[u][u] > 0:
            if step == x:
                step = step + 1
                result.appendPathFactorial(paths[u][u], x, scores[-1])
                scores.append(scores[-1] + dist[u][u])
            dfs(0, x - 1)

    def score(u, x):
        nonlocal step, dist
        if len(result) <= step < (x + 1) * (n + 1):
            result = len(result) - step
        scores.append(dist[u] + dist[step])

    while len(scores) > 1:
        score(0, x - step)
        score(result, x - step)
        dfs(0, x - step)

    while len(scores) > 1:
        result = len(result) - step
    return scores[-1]

