def shortest_paths(n, m, roads):
    from collections import defaultdict
    from math import inf

    # Initialize the distance array
    dist = {i: inf for i in range(1, n + 1)}
    dist[1] = 0
    visited = set([1])

    for _ in range(n - 1):
        for x, y, l in roads:
            if x in visited and y not in visited:
                dist[y] = l
                visited.add(y)
            if y in visited and x not in visited:
                dist[x] = l
                visited.add(x)

    # Length of the shortest path between any two cities i and j
    def shortest_length(i, j):
        if i == j:
            return 0
        return dist[i] + dist[j] if (j in dist) else 0

    # Estimate the number of roads in the shortest path
    total_roads = 0
    for u, v, w in roads:
        total_roads += w if shortest_length(u, v) == 2 * w else 0

    # Number of roads lying on safe shortest paths for each possible pair
    visited = defaultdict(int)
    safe = defaultdict(int)
    for u in range(1, n + 1):
        h = [0] * (n + 1)
        visited[u] = 1
        h[u] = 1
        for i in range(u + 1, n + 1):
            if i in visited:
                h[i] = h[u] + (dist[i] == i - u)
            else:
                h[i], safe[i], safe[u] = h[i], safe[i], safe[u] + h[i]

    for u in range(1, n + 1):
        for v in range(u + 1, n + 1):
            if (safe[u] + safe[v] == 0):
                total_roads -= 2 - h[v]
            else:
                total_roads -= 1 - h[v]

