def min_ones_after_transformations(n, m, grid):
    if n == 1:
        return sum(map(sum, grid))
    else:
        # Check all possible conditions
        target = sum(sum(row) for row in zip(*grid))
        count_set = sum(map(set, grid))
        if count_set == n:
            return target - sum(sum(row) for row in grid)
        elif count_set == 0:
            return n - target
        else:
            # Calculate the minimum number of ones possible
            total_ones = target - abs(n % 2)
            half_row = 2 * (m // 2)
            zero_in_halves = (half_row + half_row - 2) * sum(map(sum, grid))
            one_in_halves = 2 * total_ones
            # Check if exactly half the columns have values 1
            if all(1 in row for row in zip(*grid)):
                # If so, consider the overlap of zeros from both halves
                return zero_in_halves - (2 * total_ones) + 2 * n
            else:
                return zero_in_halves - (2 * total_ones)

