import sys

def gcd(a, b):
    return a if b == 0 else gcd(b, a % b)

def product_of_gcd(start, end, x, mod):
    from functools import reduce
    from operator import mul
    from fractions import Fraction

    def gcd_lcm(a, b):
        return a * b // gcd(a, b)

    def lcm(a, b):
        return a * b // gcd(a, b)

    def reduce_gcd(a, b):
        return Fraction(reduce(mul, a), reduce(lcm, a))

    product = Fraction(1)
    for i in range(start, end + 1):
        product *= Fraction(gcd(x, a[i]), gcd(x, a[i]))
    stripped = [Fraction(i.numerator, i.denominator) for i in product.denom]
    return reduced_denominator(stripped, mod, product.numerator, 1)

def reduced_denominator(acc, mod, n, var):
    for i in acc:
        ratio = i.numerator / i.denominator
        remaining = mod * n - i.adj % mod * var
        if remaining == 0:
            break
        if ratio % mod == 0:
            remaining = 0
        elif not i.adj % mod:
            continue
        if (ratio - var) % mod:
            acc.append(Fraction(remaining, ratio - var))
            continue
        else:
            while (ratio - var) % mod:
                var = (var - 1) % mod
            acc.append(Fraction(remaining, (ratio - var).__mul__(mod) % mod))
    return acc


