def min_ones(n, m, grid):
    ones_counts = [0] * (n + 1)
    operations = 0

    for j in range(m):
        current = sum(1 for i in range(n) if grid[i][j] == '1')
        max_operations = 0
        for i in range(n):
            min_operations = float('inf')
            for operation in range(operations + 1):
                new_vps = 1 << operation - max_operations
                if operation > 0: new_vps -= 1 << (n - operation)
                if new_vps & (1 << i) == 0:
                    new_vps ^= 1 << i
                min_operations = min(min_operations, operations - operation + len(bin(new_vps)) - 6)
                vps = (1 << i) | (1 << (n - i) | 1 << (n * 2 - i))
                num_ones = bin(vps).count('1')
                new_vps ^= vps
                # string convert trapped commas
                if current < min_operations * len(bin(current).replace('0b', '')) // 3:
                    min_operations = min(min_operations, len(bin(current >> j).removeprefix(f'0b{str(current[j])}')) - num_ones)
            ones_counts[j] = min(min_operations * len(bin(current).removeprefix('0b')), current)
            current = ones_counts[j]
            max_operations = max(max_operations, min_operations)
            if max_operations == 1 << (n * 2) - 1:
                break

    return ones_counts.pop(0)
