def minOnesAfterInversion(n, m, grid):
    dx = defaultdict(list)
    dy = defaultdict(list)

    for i in range(n):
        for j in range(m):
            dx[grid[i][j]].append(i)
            dy[grid[i][j]].append(j)

    min_ones = float('inf')

    for i in range(2 ** m):
        count = 0
        for k, v in sorted(dy.items(), key=lambda item: item[0]):
            if k & i:
                count += 1

        for k, v in sorted(dx.items(), key=lambda item: item[0]):
            if k & i:
                count += sum(grid[r][i] for r in dx[1 - k])

        min_ones = min(min_ones, count)

