from collections import defaultdict

def find_shortest_paths(city_dict, start, end):
    def dijkstra(graph, start):
        distances = {start: 0}
        queue = [start]
        while queue:
            u = queue.pop(0)
            for neighbor, distance in graph[u].items():
                if neighbor not in distances or distances[u] + distance < distances[neighbor]:
                    distances[neighbor] = distances[u] + distance
                    queue.append(neighbor)
        return distances

    def reconstruct_path(graph, start, end, distances):
        path = []
        current = end
        while current != start:
            path.append(current)
            for neighbor, distance in graph[current].items():
                if distances[current] - distances[neighbor] == distance:
                    current = neighbor
                    break
        path.append(start)
        return path[::-1]

    def get_shortest_path(graph, start, end):
        distances = dijkstra(graph, start)
        reversed_graph = defaultdict(dict)
        for city, neighbors in graph.items():
            for neighbor, distance in neighbors.items():
                reversed_graph[neighbor][city] = distance
        return reconstruct_path(reversed_graph, end, start, distances)

    graph = defaultdict(dict)
