def find_gcd(tree, start, end, x):
    if start == end:
        return x % mod
    elif x == 1:
        return 1

    def go_to_path(node):
        while start not in tree[node] and end not in tree[node]:
            node = tree[node][0]
        if start in tree[node]:
            return go_to_path(tree[node].index(start))
        return go_to_path(tree[node][-1])

    def go_from_path(target, node):
        while target not in tree[node]:

            if len(tree[node]) > 1:
                node = tree[node][0]
            else:
                node = tree[node][-1]

        while start not in tree[node] or end not in tree[node]:
            if len(tree[node]) > 1:
                node = tree[node][0]
            else:
                node = tree[node][-1]

        target_index = tree[node].index(target)
        if target_index == 0:
            return go_from_path(start, tree[node][0]) 
        elif target_index == len(tree[node]) - 1:
            return go_from_path(end, tree[node][-1])

