        self.adj[u].append((v, w))
        self.adj[v].append((u, w))

    def dijkstra(self, st, et):
        queue = [(0, st)]
        seen = [False] * self.n
        seen[st] = True
        prev = [-1] * self.n
        res = []
        while queue:
            dist, u = heappop(queue)
            if u == et:
                res = [0] + sorted(res)[::-1]
                return max(self.dust[u] - dist, 0) + sum(self.dust[node] for node, _ in self.ranks[et] if node != et)
            for v, w in self.adj[u]:
                if seen[v]:
                    continue
                new_dist = dist + w
                if not seen[v] or (seen[v] and self.dust[u] < new_dist):
                    prev[v] = u
                    heappush(queue, (new_dist, v))
                    seen[v] = True
            seen[u] = False
            if self.distances[u] < dist:
                continue
            heappush(queue, (dist + self.distances[u] + self.dust[u], u))
