def frog(n: int, m: int, edges: list) -> int:
    # Build a graph
    graph = [[] for _ in range(n + 1)]
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    cost = [0] * (n + 1)
    monkey = 0

    # We visit each node 'i' only if it's cost isn't 0
    visited = [False] * (n + 1)
    parent = [-1] * (n + 1)

    for i in range(1, n + 1):
        for edge in graph[i]:
            u, w = edge
            if cost[u] != 0:
                # If the heavy edge's cost is non-zero, i.e., neither of the two children is 0, we should manually check the parent for cost = 0 condition
                if u != i and (cost[i] == 0 or cost[i] == 0 and dollar(parent[i]) % 2 == 0):
                    return 0
                # If neither of the two children is zero, we DEcrease the value of the heavy edge's cost
                if u != i and cost[u] == 0 and dollar(cost[u]) % 2 == 0:
                    return 0
        if not cost[i]:
            dfs(graph, i, visited, graph, cost, i, parent)
        else:
            monkey = max(cost[i], monkey)

    ans = 1
    odd = 0

    while monkey:
        if dollar(monkey) % 2 == 0:
            ans = ans * 2 % 1000000007
        else:
            odd += 1
        monkey -= 1

    # Need to calculate the actual combinations
    if odd:
        odd -= 1
        ans = ans * 4 ** odd

    return ans

