from functools import cache
from collections import defaultdict

def min_cost_cycle(graph, nodes, edges_cost, cycle_cost=1):
    n = len(graph)
    inf = 10**18
    g = defaultdict(lambda: [inf] * (nodes + 1))

    for u in range(1, nodes + 1):
        g[u][u] = 0
        for v, w in graph[u]:
            g[u][v] = w

    for e in edges_cost:
        u, v, w = e[0], e[1], e[2]
        # We can check if u -> v is clique
        g[u][v] = 0
        # We can check if v -> u is clique
        g[v][u] = 0

    @cache
    def dp(n):
        # Base case
        if n == 1:
            return 0

        # Recursive step
        partial = []
        start, end = -inf, inf
        for u in range(1, n + 1):
            partial.append(g[u][1])
            if g[u][1] == inf:
                if start == -inf:
                    start = u
            elif g[u][1] < start and partial[-1] > cycle_cost:
                end = u
        return sum(min(a + b for a in partial if a > 0) for b in range(cycle_cost, start + 1))

    return dp(nodes)
